        new Quote { Id = "https://it.wikiquote.org/wiki/Leucippo", Text = "Nulla avviene a caso, tutto secondo ragione e necessità.", Author = "Leucippo" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Ferdinando_Fontana", Text = "Io dico che l'esperienza mi ha insegnato esservi molte donne che simulano la virtù per rendere più prezioso il peccato.", Author = "Ferdinando Fontana" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Adriaan_van_Baerland", Text = "La bellezza e la magnificenza degli edifici pubblici e privati è indescrivibile. Si può dire in poche parole che non c'è niente che non dia godimento alla vista e alla mente. Gand, Anversa, Bruxelles, Lovanio e Malines sono senza dubbio belle città, ma non sono nulla in confronto a Bruges.", Author = "Adriaan van Baerland" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Stieg_Larsson", Text = "Era sorpresa di essere ancora viva. Notò che stranamente non le importava nulla. Se la morte era il vuoto nero dal quale si era appena svegliata, allora non era niente per cui angustiarsi. Non avrebbe mai notato la differenza. (da La regina dei castelli di carta, p. 75)", Author = "Stieg Larsson" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Zorro_%28serie_televisiva_1957%29", Text = "Quando il nemico è molto forte bisogna fare diversamente. Conosci il vecchio proverbio. Quando non puoi indossare la pelle del leone, indossa quella della volpe. (Don Diego)", Author = "Zorro (serie televisiva 1957)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Mulino_ad_acqua", Text = "Vecchio mulino | oggi io mi sento | una delle tue pale. | Ruoto lentamente | con la ruota | e poi mi immergo | nell'acqua grigia | per risalire poi | verso un caldo vento | e un sole di campagna. (Riccardo Mannerini)", Author = "Mulino ad acqua" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Anselm_Kiefer", Text = "Non ho mai inventato nulla. Forse più di altri ho mostrato ciò che esisteva già. In una luce diversa.", Author = "Anselm Kiefer" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Ferruccio_Alessandri", Text = "Tutti noi siamo vittime dell'abitudine più profondamente di quanto possiamo pensare, e questo per abitudine.", Author = "Ferruccio Alessandri" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Paolo_Pietrangeli", Text = "[Sul razzismo in Italia] È diventata un brutto paese. Dove si discute ancora del colore della pelle, argomenti che quando io ero studente erano già risolti.", Author = "Paolo Pietrangeli" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Philip_Sidney", Text = "Non saranno mai soli se accompagnati da nobili pensieri.", Author = "Philip Sidney" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Carlo_Maria_Martini", Text = "Spesso il linguaggio usato per parlare di Dio è stentato e fiacco, a volte imbarazzato, a volte generico; ci si divide facilmente in verticalisti e orizzontalisti, tradizionalisti e progressisti, si formulano giudizi che, alla luce del Vangelo, risultano perlomeno inadeguati.", Author = "Carlo Maria Martini" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Arrigo_Levi", Text = "Meglio avere la coscienza dell'incerto che avere false certezze.", Author = "Arrigo Levi" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Rhetorica_ad_Herennium", Text = "Deligere oportet quem velis diligere.", Author = "Rhetorica ad Herennium" },
        new Quote { Id = "https://it.wikiquote.org/wiki/San_Paolo_%28miniserie_televisiva%29", Text = "La mia forza è nella tenacia, Ruben. Quando ho un obiettivo non mi arrendo mai. (Saul)", Author = "San Paolo (miniserie televisiva)" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Audioslave", Text = "Staring at the loss, looking for a cause, and never really sure. Nothing but a hole to live without a soul and nothing to be learned. (da Shadow on the sun)", Author = "Audioslave" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Alfredo_Cerruti", Text = "Mi piaceva dormire, è vero. Magari fino a mezzogiorno. Però in ufficio andavo e stavo sempre molto attento a non trasformare il lavoro in ossessione.", Author = "Alfredo Cerruti" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Falcomat%C3%A0", Text = "Pensa cosa sarebbe il mondo se ognuno, nella storia, si fosse fermato al primo lascia perdere. (Cap.XXX, p.208)", Author = "Giuseppe Falcomatà" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Wies%C5%82aw_Brudzi%C5%84ski", Text = "Gli affari peggiori si fanno con gli altruisti.", Author = "Wiesław Brudziński" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Tiberio_Murgia", Text = "[Su La grande guerra] Quel film per la fatica delle scene è stato come fare il militare per dav­vero.", Author = "Tiberio Murgia" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Paolo_Monti", Text = "Il paese non riconosce un fotogiornalista come giornalista.", Author = "Paolo Monti" },
        new Quote { Id = "https://it.wikiquote.org/wiki/Anselmo_Bucci", Text = "Ama soltanto quello che non sai fare.", Author = "Anselmo Bucci" }
